import static bootcamp.Check.*;

import java.util.*;
import java.util.stream.*;

class Exercise {

    /** {count, sum, min, max} in one pass. */
    static long[] statsOf(List<Integer> xs) {
        IntSummaryStatistics s = xs.stream().collect(Collectors.summarizingInt(Integer::intValue));
        return new long[] {s.getCount(), s.getSum(), s.getMin(), s.getMax()};
    }

    /** max - min. */
    static int spread(List<Integer> xs) {
        IntSummaryStatistics s = xs.stream().collect(Collectors.summarizingInt(Integer::intValue));
        return s.getMax() - s.getMin();
    }

    // ─── tests ───────────────────────────────────────────────────────────
