// ─────────────────────────────────────────────────────────────────────────
//  06 · two collectors, one pass                                     ★★★
//  concepts: Collectors.teeing · summingInt + counting · minBy + maxBy
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.stream.*;

class Exercise {

    /** sum / count in one pass. */
    static long averageCents(List<Integer> prices) {
        return prices.stream().collect(Collectors.teeing(Collectors.summingInt(x -> x), Collectors.counting(), (sum, n) -> sum / n));
    }

    /** {min, max} in one pass. */
    static int[] range(List<Integer> xs) {
        return xs.stream().collect(Collectors.teeing(
            Collectors.minBy(Comparator.<Integer>naturalOrder()),
            Collectors.maxBy(Comparator.<Integer>naturalOrder()),
            (min, max) -> new int[] {min.orElseThrow(), max.orElseThrow()}));
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("average of three prices", () ->
            eq(averageCents(List.of(100, 200, 300)), 200));
        test("equal prices average to themselves (boundary)", () ->
            eq(averageCents(List.of(250, 250)), 250));
        test("range finds both ends", () ->
            eq(range(List.of(4, 9, 1)), new int[] {1, 9}));
        test("a single value is both ends (boundary)", () ->
            eq(range(List.of(5)), new int[] {5, 5}));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

